$regions=db()->query('SELECT * FROM regions ORDER BY sort_order,name')->fetchAll();$rows=db()->query("SELECT w.*,rb.name bujang_region,rd.name dayang_region FROM winners w LEFT JOIN regions rb ON rb.id=w.bujang_region_id LEFT JOIN regions rd ON rd.id=w.dayang_region_id ORDER BY w.year DESC")->fetchAll();require __DIR__.'/partials/header.php';
